/*
 * Version script for the libc.so shim.
 *
 * Defines the bionic version node `LIBC` and exports exactly the symbols that
 * the vendor's libthermometry.so requires.  Everything else is hidden, so the
 * shim cannot accidentally interpose on unrelated lookups.
 *
 * Keep this list in sync with:
 *   nm -D --undefined-only libthermometry.so
 */

LIBC {
  global:
    __cxa_atexit;
    __cxa_finalize;
    __stack_chk_fail;
    __stack_chk_guard;
    basename;
    exp;
    gettid;
    pow;
    puts;
    sqrt;
    sqrtf;

  local:
    *;
};
